from pathlib import Path
import json,pandas as pd,numpy as np,argparse
ap=argparse.ArgumentParser();ap.add_argument('--science',required=True);ap.add_argument('--newout',required=True);a=ap.parse_args();sc=Path(a.science);out=Path(a.newout);out.mkdir(parents=True,exist_ok=False)
def read(n):return pd.read_csv(sc/n)
aud=json.loads((sc/'data/audit_extended.json').read_text('utf-8'));bound=read('data/snapshot_boundaries.csv');mem=read('uncertainty/pool_membership_all_origins.csv');h=read('results/historical_predictions_plans.csv');v=h[(h.stage=='validation')&(h.policy=='stochastic')];f=read('results/future_daily_summary.csv');res={'audit':aud,'boundaries':bound.to_dict('records'),'pool_by_origin':mem.groupby(['calibration_origin','method_id']).eligible.agg(['sum','count']).reset_index().to_dict('records'),'validation_by_origin':read('results/group_origin_stage_method_id_policy.csv').query("stage=='validation' and policy=='stochastic'").to_dict('records'),'activity_groups':read('results/group_stage_method_id_policy_holiday.csv').query("stage=='validation' and policy=='stochastic'").to_dict('records'),'interval_levels_validation':read('results/interval_tradeoff.csv').query("stage=='validation'").groupby(['method_id','nominal_level'])[['coverage','width_units']].mean().reset_index().to_dict('records'),'sensitivity':read('results/sensitivity.csv').to_dict('records'),'bootstrap':json.loads((sc/'results/paired_loss_diagnostic.json').read_text('utf-8')),'oracle':json.loads((sc/'validation/optimizer_tests.json').read_text('utf-8'))}
for col in ['horizon','store_id','item_id']:
    t=v.groupby(['method_id',col]).agg(rows=('actual','size'),days=('service_date','nunique'),abs_sum=('abs_error','sum'),covered=('covered','mean'),loss=('shortage_yuan','sum'),waste=('waste_yuan','sum')).reset_index();t['mae']=t.abs_sum/t.rows;t['loss_per_day']= (t.loss+t.waste)/t.days
    if col=='horizon':t['lead_group']=np.where(t.horizon<=7,'1-7','8-14');t2=v.assign(lead_group=np.where(v.horizon<=7,'1-7','8-14')).groupby(['method_id','lead_group']).agg(mae=('abs_error','mean'),coverage=('covered','mean'),n=('actual','size')).reset_index();res['lead_groups']=t2.to_dict('records')
    else:res['validation_'+col]=t[['method_id',col,'mae','loss_per_day','covered']].to_dict('records')
    t.to_csv(out/f'validation_{col}.csv',index=False)
future=[]
for name,z in f.groupby('method_id'):
    future.append({'method_id':name,'capacity_binding_days':int((z.capacity_slack==0).sum()),'budget_binding_days':int((z.budget_slack_yuan.abs()<1e-8).sum()),'min_q':int(z.q_units.min()),'max_q':int(z.q_units.max()),'max_budget':float(z.procurement_yuan.max()),'mean_point_total':float(z.point_total_units.mean()),'mean_q':float(z.q_units.mean()),'mean_budget':float(z.procurement_yuan.mean()),'mean_shortage_scenario':float(z.scenario_shortage_yuan.mean()),'mean_waste_scenario':float(z.scenario_waste_yuan.mean())})
    p=read(f'future/{name}/predictions.csv').merge(read(f'future/{name}/replenishment.csv'),on=['service_date','store_id','item_id','method_id']);p['week']=((pd.to_datetime(p.service_date)-pd.Timestamp('2026-11-01')).dt.days//7+1)
    for col in ['item_id','store_id','week']:p.groupby(col).agg(total_point_units=('demand_point_units','sum'),total_q_units=('q_units','sum'),mean_lower=('lower90_units','mean'),mean_upper=('upper90_units','mean')).reset_index().to_csv(out/f'future_allocation_{name}_{col}.csv',index=False)
res['future_resource']=future;res['future_week_allocation']=pd.read_csv(out/'future_allocation_shared_ridge10_week.csv').to_dict('records');res['future_item_allocation']=pd.read_csv(out/'future_allocation_shared_ridge10_item_id.csv').to_dict('records');res['fit_runtimes_by_method']=read('results/fit_runtime.csv').groupby('method_id').fit_predict_seconds.agg(['sum','max']).reset_index().to_dict('records')
with (out/'inspection.json').open('x',encoding='utf-8') as fobj:json.dump(res,fobj,ensure_ascii=False,indent=2)
print(json.dumps(res,ensure_ascii=False,indent=2))
